for kv_block in blocks(K, V):
    K_sram, V_sram = load_to_sram(kv_block)
    for q_block in blocks(Q):
        Q_sram = load_to_sram(q_block)
        scores = Q_sram @ K_sram.T
        m_new, l_new, acc_new = online_softmax_update(scores, V_sram, state[q_block])
        state[q_block] = (m_new, l_new, acc_new)

for q_block in blocks(Q):
    write_hbm(output[q_block], normalize(state[q_block]))

# Backward recomputes score tiles instead of loading a saved N x N attention matrix.
